96.     fn new(base: PageAligned<PhysicalAddress>, bitmap: Bitmap) -> Result<Inner, Error> {
97.         // Check if bitmap spans across physically-addressable memory.
98.         let bitmap_capacity: usize = bitmap.number_of_bits();
99.         let kpool_size: usize = match bitmap_capacity.checked_mul(mem::PAGE_SIZE) {
100.             Some(size) => size,
101.             None => {
102.                 let reason: &str = "kernel pool size overflows addressable memory";
103.                 #[cfg(not(verus_keep_ghost))]
104.                 error!("{reason}");
105.                 return Err(Error::new(ErrorCode::InvalidArgument, reason));
106.             },
107.         };
108.         // VERUS REWRITE: pa_into_raw wrapper needed because Verus cannot resolve generic trait .into_raw_value()
109.         if !is_valid_physical_region(pa_into_raw(base), kpool_size) {
110.             let reason: &str = "kernel pool bitmap spans across physically-addressable memory";
111.             #[cfg(not(verus_keep_ghost))]
112.             error!("{reason}");
113.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
114.         }
115.         #[cfg(not(verus_keep_ghost))]
116.         info!("kernel pool: {} frames, {} KB", bitmap_capacity, kpool_size / 1024,);
117. 
118.         proof! {
119.             // kpool_size == bitmap_capacity * PAGE_SIZE == bitmap@.num_bits * spec_page_size()
120.             // is_valid_physical_region returned true, so base@ + kpool_size <= usize::MAX + 1
121.             assert(spec_page_size() > 0);
122.             assert(bitmap@.num_bits == bitmap_capacity as int);
123.             assert(kpool_size as int == bitmap_capacity as int * spec_page_size());
124.             assert(base@ + kpool_size as int <= usize::MAX as int + 1);
125.             assert(base@ >= 0);
126.         }
127. 
128.         // VERUS REWRITE: intermediate binding for proof block (pre-approved deviation)
129.         let inner = Inner { base, bitmap };
130.         proof! {
131.             inner.lemma_internal_inv_intro();
132.         }
133.         Ok(inner)
134.     }
135. 
