         assert forall|addr: int| self@.free_frames.contains(addr) implies addr % ps == 0
         by {
             let i = choose|i: int| self.bitmap@.is_covered(i) && !self.bitmap@.set_bits.contains(i) && addr == frame_addr_of(i);
             assert(addr == i * ps);
             lemma_mod_multiples_basic(i, ps);
