/// Proves index * page_size doesn't overflow and base + index * page_size ≤ usize::MAX.
proof fn lemma_index_mul_no_overflow(base: int, index: int, num_bits: int, ps: int)
    requires
        ps > 0,
        base >= 0,
        0 <= index < num_bits,
        base + num_bits * ps <= usize::MAX as int + 1,
    ensures
        index * ps < num_bits * ps,
        index * ps <= usize::MAX as int,
        base + index * ps <= usize::MAX as int,
{
    vstd::arithmetic::mul::lemma_mul_strict_inequality(index, num_bits, ps);
}

/// Proves (base + k * page_size) % page_size == 0 when base is page-aligned.
proof fn lemma_addr_page_aligned(base: int, k: int, ps: int)
    requires
        ps > 0,
        base % ps == 0,
    ensures
        (base + k * ps) % ps == 0,
{
    vstd::arithmetic::div_mod::lemma_mod_multiples_vanish(k, base, ps);
}

/// Proves (k * page_size) / page_size == k.
proof fn lemma_page_index_eq(k: int, ps: int)
    requires
        ps > 0,
    ensures
        (k * ps) / ps == k,
{
    vstd::arithmetic::div_mod::lemma_div_by_multiple(k, ps);
}

/// Proves a / d < 0 when a < 0 and d > 0.
proof fn lemma_negative_div(a: int, d: int)
    requires
        a < 0,
        d > 0,
    ensures
        a / d < 0,
{
    vstd::arithmetic::div_mod::lemma_fundamental_div_mod(a, d);
    let q: int = a / d;
    let r: int = a % d;
    assert(a == d * q + r);
    assert(0 <= r);
    if q >= 0 {
        vstd::arithmetic::mul::lemma_mul_inequality(0, q, d);
    }
}

/// Proves base_addr + i * ps == base + (index + i) * ps (distributivity).
proof fn lemma_offset_sum(base: int, index: int, i: int, ps: int)
    requires
        ps > 0,
    ensures
        (index + i) * ps == index * ps + i * ps,
        base + (index + i) * ps == base + index * ps + i * ps,
{
    vstd::arithmetic::mul::lemma_mul_is_distributive_add_other_way(ps, index, i);
}

/// Proves (index + i) * ps == index * ps + i * ps (for postcondition).
proof fn lemma_mul_distributive(ps: int, a: int, b: int)
    requires
        ps > 0,
    ensures
        (a + b) * ps == a * ps + b * ps,
{
    vstd::arithmetic::mul::lemma_mul_is_distributive_add(ps, a, b);
}

/// Proves range_free is false when bitmap has no contiguous free range.
proof fn lemma_no_free_range(
    kview: KpoolView,
    bview: BitmapView,
    count: int,
)
    requires
        count > 0,
        kview.num_pages == bview.num_bits,
        kview.used_page_indices == bview.set_bits,
        !bview.exists_contiguous_free_range(count),
    ensures
        forall|start: int| !kview.range_free(start, count),
{
    assert forall|start: int| !kview.range_free(start, count) by {
        if kview.range_free(start, count) {
            assert(0 <= start <= kview.num_pages - count);
            assert(start + count <= bview.num_bits);
            assert forall|j: int| start <= j < start + count
                implies !bview.is_bit_set(j) by {};
            assert(bview.all_bits_unset_in_range(start, start + count));
            assert(bview.has_free_range_at(start, count));
            assert(false);
        }
    };
}

} // end verus!

