    assert(self@.used_page_indices =~= old(self)@.used_page_indices.union(new_page_indices));
    // num_pages unchanged
    assert(self@.num_pages == old(self)@.num_pages);
    // start unchanged
    assert(self@.start == old(self)@.start);
}

