3. use super::KpoolView;
4. 
5. impl View for Inner {
6.     type V = KpoolView;
7. 
8.     closed spec fn view(&self) -> KpoolView
9.     {
10.         KpoolView{
11.             start: self.base@,
12.             num_pages: self.bitmap@.num_bits as int,
13.             used_page_indices: self.bitmap@.set_bits,
14.         }
15.     }
16. }
17. 
18. impl Inner {
19.     pub closed spec fn internal_inv(&self) -> bool
20.     {
21.         &&& self.base.inv()
22.         &&& self.bitmap.inv()
23.         &&& spec_page_size() > 0
24.         &&& self.base@ >= 0
25.         &&& self.base@ + self.bitmap@.num_bits * spec_page_size() <= usize::MAX as int + 1
26.         &&& self.bitmap@.num_bits < u32::MAX as int
27.     }
28. 
29.     /// Reveals all conjuncts of internal_inv for use in proof blocks.
30.     proof fn lemma_internal_inv(&self)
31.         requires self.internal_inv(),
32.         ensures
33.             self.base.inv(),
34.             self.bitmap.inv(),
35.             spec_page_size() > 0,
36.             self.base@ >= 0,
37.             self.base@ + self.bitmap@.num_bits * spec_page_size() <= usize::MAX as int + 1,
38.             self.bitmap@.num_bits < u32::MAX as int,
39.     {}
40. 
41.     /// Establish internal_inv from its individual conjuncts.
42.     proof fn lemma_internal_inv_intro(&self)
43.         requires
44.             self.base.inv(),
45.             self.bitmap.inv(),
46.             spec_page_size() > 0,
47.             self.base@ >= 0,
48.             self.base@ + self.bitmap@.num_bits * spec_page_size() <= usize::MAX as int + 1,
49.             self.bitmap@.num_bits < u32::MAX as int,
50.         ensures self.internal_inv(),
51.     {}
52. }
53. 
54. /// Proves index * page_size doesn't overflow and base + index * page_size ≤ usize::MAX.
55. #[verifier::spinoff_prover]
56. proof fn lemma_index_mul_no_overflow(base: int, index: int, num_bits: int, ps: int)
57.     requires
58.         ps > 0,
59.         base >= 0,
60.         0 <= index < num_bits,
61.         base + num_bits * ps <= usize::MAX as int + 1,
62.     ensures
63.         index * ps < num_bits * ps,
64.         index * ps <= usize::MAX as int,
65.         base + index * ps <= usize::MAX as int,
66. {
67.     vstd::arithmetic::mul::lemma_mul_strict_inequality(index, num_bits, ps);
68. }
69. 
70. /// Proves (base + k * page_size) % page_size == 0 when base is page-aligned.
71. #[verifier::spinoff_prover]
72. proof fn lemma_addr_page_aligned(base: int, k: int, ps: int)
73.     requires
74.         ps > 0,
75.         base % ps == 0,
76.     ensures
77.         (base + k * ps) % ps == 0,
78. {
79.     vstd::arithmetic::div_mod::lemma_mod_multiples_vanish(k, base, ps);
80. }
81. 
82. /// Proves (k * page_size) / page_size == k.
83. #[verifier::spinoff_prover]
84. proof fn lemma_page_index_eq(k: int, ps: int)
85.     requires
86.         ps > 0,
87.         k >= 0,
88.     ensures
89.         (k * ps) / ps == k,
90. {
91.     vstd::arithmetic::div_mod::lemma_div_by_multiple(k, ps);
92. }
93. 
94. /// Proves a / d < 0 when a < 0 and d > 0.
95. #[verifier::spinoff_prover]
96. proof fn lemma_negative_div(a: int, d: int)
97.     requires
98.         a < 0,
99.         d > 0,
100.     ensures
101.         a / d < 0,
102. {
103.     vstd::arithmetic::div_mod::lemma_fundamental_div_mod(a, d);
104.     let q: int = a / d;
105.     let r: int = a % d;
106.     assert(a == d * q + r);
107.     assert(0 <= r);
108.     if q >= 0 {
109.         vstd::arithmetic::mul::lemma_mul_inequality(0, q, d);
110.     }
111. }
112. 
113. /// Proves base_addr + i * ps == base + (index + i) * ps (distributivity).
114. #[verifier::spinoff_prover]
115. proof fn lemma_offset_sum(base: int, index: int, i: int, ps: int)
116.     requires
117.         ps > 0,
118.     ensures
119.         (index + i) * ps == index * ps + i * ps,
120.         base + (index + i) * ps == base + index * ps + i * ps,
121. {
122.     vstd::arithmetic::mul::lemma_mul_is_distributive_add_other_way(ps, index, i);
123. }
124. 
125. /// Proves (index + i) * ps == index * ps + i * ps (for postcondition).
126. #[verifier::spinoff_prover]
127. proof fn lemma_mul_distributive(ps: int, a: int, b: int)
128.     requires
129.         ps > 0,
130.     ensures
131.         (a + b) * ps == a * ps + b * ps,
132. {
133.     vstd::arithmetic::mul::lemma_mul_is_distributive_add(ps, a, b);
134. }
135. 
136. /// Proves range_free is false when bitmap has no contiguous free range.
137. #[verifier::spinoff_prover]
138. proof fn lemma_no_free_range(
139.     kview: KpoolView,
140.     bview: BitmapView,
141.     count: int,
142. )
143.     requires
144.         count > 0,
145.         kview.num_pages == bview.num_bits,
146.         kview.used_page_indices == bview.set_bits,
147.         !bview.exists_contiguous_free_range(count),
148.     ensures
149.         forall|start: int| !kview.range_free(start, count),
150. {
151.     assert forall|start: int| !kview.range_free(start, count) by {
152.         if kview.range_free(start, count) {
153.             assert(0 <= start <= kview.num_pages - count);
154.             assert(start + count <= bview.num_bits);
155.             assert forall|j: int| start <= j < start + count
156.                 implies !bview.is_bit_set(j) by {};
157.             assert(bview.all_bits_unset_in_range(start, start + count));
